import poissonDistribution from '../../src/poisson_distribution.js';

describe('poissonDistribution', () => {
    // Test basic functionality with different lambda values
    test('should return correct distribution for lambda = 1', () => {
        const result = poissonDistribution(1);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // Verify probabilities sum to approximately 1 (within reasonable tolerance)
        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);

        // Verify first few values match Poisson PMF for lambda=1
        expect(result[0]).toBeCloseTo(Math.exp(-1), 10);
        expect(result[1]).toBeCloseTo(Math.exp(-1), 10);
        expect(result[2]).toBeCloseTo(Math.exp(-1) / 2, 10);
    });

    test('should return correct distribution for lambda = 2.5', () => {
        const lambda = 2.5;
        const result = poissonDistribution(lambda);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // Verify probabilities sum to approximately 1 (within reasonable tolerance)
        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);

        // Verify first value matches Poisson PMF
        expect(result[0]).toBeCloseTo(Math.exp(-lambda), 10);

        // Verify relationship between consecutive probabilities
        for (let i = 0; i < Math.min(5, result.length - 1); i++) {
            const expected = result[i] * lambda / (i + 1);
            expect(result[i + 1]).toBeCloseTo(expected, 10);
        }
    });

    test('should return correct distribution for lambda = 0.5', () => {
        const lambda = 0.5;
        const result = poissonDistribution(lambda);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // Verify probabilities sum to approximately 1 (within reasonable tolerance)
        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);

        // Verify first few values
        expect(result[0]).toBeCloseTo(Math.exp(-lambda), 10);
        expect(result[1]).toBeCloseTo(lambda * Math.exp(-lambda), 10);
    });

    test('should return correct distribution for lambda = 10', () => {
        const lambda = 10;
        const result = poissonDistribution(lambda);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // Verify probabilities sum to approximately 1 (within reasonable tolerance)
        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);

        // Verify distribution has reasonable length
        expect(result.length).toBeGreaterThan(10);
        expect(result.length).toBeLessThan(50);
    });

    // Test edge cases
    test('should return undefined for lambda = 0', () => {
        const result = poissonDistribution(0);
        expect(result).toBeUndefined();
    });

    test('should return undefined for negative lambda', () => {
        const result = poissonDistribution(-1);
        expect(result).toBeUndefined();
    });

    test('should return undefined for lambda = -5.5', () => {
        const result = poissonDistribution(-5.5);
        expect(result).toBeUndefined();
    });

    // Test very small lambda
    test('should handle very small lambda values', () => {
        const lambda = 0.001;
        const result = poissonDistribution(lambda);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // For very small lambda, most probability should be at x=0
        expect(result[0]).toBeCloseTo(Math.exp(-lambda), 10);
        expect(result[0]).toBeGreaterThan(0.99);

        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);
    });

    // Test large lambda
    test('should handle large lambda values', () => {
        const lambda = 100;
        const result = poissonDistribution(lambda);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // Distribution should be reasonably sized
        // For lambda=100, 3*sqrt(lambda) ≈ 30, so range is 70-130
        // But algorithm may go slightly beyond due to epsilon
        expect(result.length).toBeGreaterThan(70);
        expect(result.length).toBeLessThan(150);

        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);
    });

    // Test that cumulative probability condition is met
    test('should stop when cumulative probability reaches 1 - epsilon', () => {
        const lambda = 3;
        const result = poissonDistribution(lambda);

        // Calculate cumulative probability up to last element
        let cumulative = 0;
        for (let i = 0; i < result.length; i++) {
            cumulative += result[i];
        }

        // The cumulative probability should be >= 1 - epsilon (using reasonable epsilon)
        expect(cumulative).toBeGreaterThanOrEqual(0.9999);
        expect(cumulative).toBeLessThanOrEqual(1);
    });

    // Test that all probabilities are non-negative
    test('should return only non-negative probabilities', () => {
        const testLambdas = [0.1, 1, 2.5, 5, 10, 20];

        testLambdas.forEach(lambda => {
            const result = poissonDistribution(lambda);
            result.forEach(probability => {
                expect(probability).toBeGreaterThanOrEqual(0);
            });
        });
    });

    // Test that probabilities decrease after mode for lambda >= 1
    test('probabilities should be unimodal for lambda >= 1', () => {
        const lambda = 4.7;
        const result = poissonDistribution(lambda);

        // Find the mode (floor(lambda) for Poisson)
        const mode = Math.floor(lambda);

        // Probabilities should increase up to mode
        for (let i = 1; i <= mode; i++) {
            expect(result[i]).toBeGreaterThan(result[i - 1]);
        }

        // Probabilities should decrease after mode
        for (let i = mode + 1; i < result.length - 1; i++) {
            expect(result[i]).toBeLessThan(result[i - 1]);
        }
    });

    // Test floating point lambda
    test('should handle non-integer lambda values', () => {
        const lambda = 3.14159;
        const result = poissonDistribution(lambda);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);
    });

    // Test that the function uses the epsilon value from the source
    test('should use epsilon from source for stopping condition', () => {
        const lambda = 5;
        const result = poissonDistribution(lambda);

        // The sum should be close to 1 but not necessarily exactly 1
        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);
    });

    // Test that distribution has correct properties
    test('should return decreasing probabilities for lambda < 1', () => {
        const lambda = 0.7;
        const result = poissonDistribution(lambda);

        // For lambda < 1, probabilities should be strictly decreasing
        for (let i = 1; i < result.length - 1; i++) {
            expect(result[i]).toBeLessThan(result[i - 1]);
        }
    });

    // Test boundary case
    test('should handle lambda = 1 (boundary case)', () => {
        const result = poissonDistribution(1);
        expect(result).toBeDefined();
        expect(Array.isArray(result)).toBe(true);

        // For lambda = 1, P(0) = P(1)
        expect(result[0]).toBeCloseTo(result[1], 10);

        const sum = result.reduce((acc, val) => acc + val, 0);
        expect(sum).toBeGreaterThanOrEqual(0.9999);
        expect(sum).toBeLessThanOrEqual(1);
    });
});

