import combinationsReplacement from '../../src/combinations_replacement.js';

describe('combinationsReplacement', () => {
    test('should return empty array for empty input array', () => {
        const result = combinationsReplacement([], 2);
        expect(result).toEqual([]);
    });

    test('should return single-element combinations when k=1', () => {
        const input = [1, 2, 3];
        const result = combinationsReplacement(input, 1);
        const expected = [[1], [2], [3]];
        expect(result).toEqual(expected);
    });

    test('should generate combinations with replacement for k=2', () => {
        const input = [1, 2];
        const result = combinationsReplacement(input, 2);
        const expected = [
            [1, 1],
            [1, 2],
            [2, 2]
        ];
        expect(result).toEqual(expected);
    });

    test('should generate combinations with replacement for k=3', () => {
        const input = [1, 2];
        const result = combinationsReplacement(input, 3);
        const expected = [
            [1, 1, 1],
            [1, 1, 2],
            [1, 2, 2],
            [2, 2, 2]
        ];
        expect(result).toEqual(expected);
    });

    test('should handle larger arrays with k=2', () => {
        const input = [1, 2, 3];
        const result = combinationsReplacement(input, 2);
        const expected = [
            [1, 1],
            [1, 2],
            [1, 3],
            [2, 2],
            [2, 3],
            [3, 3]
        ];
        expect(result).toEqual(expected);
    });

    test('should handle string elements', () => {
        const input = ['a', 'b'];
        const result = combinationsReplacement(input, 2);
        const expected = [
            ['a', 'a'],
            ['a', 'b'],
            ['b', 'b']
        ];
        expect(result).toEqual(expected);
    });

    test('should handle mixed type elements', () => {
        const input = [1, 'a', true];
        const result = combinationsReplacement(input, 2);
        const expected = [
            [1, 1],
            [1, 'a'],
            [1, true],
            ['a', 'a'],
            ['a', true],
            [true, true]
        ];
        expect(result).toEqual(expected);
    });

    test('should return single combination when array has one element and k=3', () => {
        const input = [5];
        const result = combinationsReplacement(input, 3);
        const expected = [[5, 5, 5]];
        expect(result).toEqual(expected);
    });

    test('should handle k larger than array length', () => {
        const input = [1, 2];
        const result = combinationsReplacement(input, 5);
        expect(result.length).toBeGreaterThan(0);
        expect(result[0]).toHaveLength(5);
        expect(result.every(comb => comb.length === 5)).toBe(true);
    });

    test('should maintain order as in original array', () => {
        const input = [3, 1, 2];
        const result = combinationsReplacement(input, 2);
        const firstCombination = result[0];
        expect(firstCombination).toEqual([3, 3]);
    });

    test('should generate correct number of combinations', () => {
        const n = 4;
        const k = 3;
        const input = [1, 2, 3, 4];
        const result = combinationsReplacement(input, k);

        // Calculate combinations with replacement formula: C(n + k - 1, k)
        const factorial = (num) => {
            if (num <= 1) return 1;
            return num * factorial(num - 1);
        };

        const expectedCount = factorial(n + k - 1) / (factorial(k) * factorial(n - 1));
        expect(result.length).toBe(expectedCount);
    });
});

