    });

    test('should return single permutation for single element array', () => {
        const result = permutationsHeap([1]);
        expect(result).toEqual([[1]]);
    });

    test('should generate all permutations for two elements', () => {
        const result = permutationsHeap([1, 2]);
        expect(result).toEqual([
            [1, 2],
            [2, 1]
        ]);
    });

    test('should generate all permutations for three elements', () => {
        const result = permutationsHeap([1, 2, 3]);
        const expectedPermutations = [
            [1, 2, 3],
            [2, 1, 3],
            [3, 1, 2],
            [1, 3, 2],
            [2, 3, 1],
            [3, 2, 1]
        ];
        expect(result).toEqual(expectedPermutations);
    });

    test('should generate all permutations for array with duplicate values', () => {
        const result = permutationsHeap([1, 1, 2]);
        const expectedPermutations = [
            [1, 1, 2],
            [1, 1, 2],
            [2, 1, 1],
            [1, 2, 1],
            [1, 2, 1],
            [2, 1, 1]
        ];
        expect(result).toEqual(expectedPermutations);
    });

    test('should generate correct number of permutations (n!)', () => {
        const testCases = [
            { input: [], expectedCount: 1 },
            { input: [1], expectedCount: 1 },
            { input: [1, 2], expectedCount: 2 },
            { input: [1, 2, 3], expectedCount: 6 },
            { input: [1, 2, 3, 4], expectedCount: 24 }
        ];

        testCases.forEach(({ input, expectedCount }) => {
            const result = permutationsHeap(input);
            expect(result.length).toBe(expectedCount);
        });
    });

    test('should work with string elements', () => {
        const result = permutationsHeap(['a', 'b', 'c']);
        const expectedPermutations = [
            ['a', 'b', 'c'],
            ['b', 'a', 'c'],
            ['c', 'a', 'b'],
            ['a', 'c', 'b'],
            ['b', 'c', 'a'],
            ['c', 'b', 'a']
        ];
        expect(result).toEqual(expectedPermutations);
    });

    test('should work with mixed type elements', () => {
        const result = permutationsHeap([1, 'a', true]);
        const expectedPermutations = [
            [1, 'a', true],
            ['a', 1, true],
            [true, 1, 'a'],
            [1, true, 'a'],
            ['a', true, 1],
            [true, 'a', 1]
        ];
        expect(result).toEqual(expectedPermutations);
    });

    test('should return independent array copies', () => {
        const result = permutationsHeap([1, 2]);
        result[0][0] = 99;
        result[1][0] = 100;
        const newResult = permutationsHeap([1, 2]);
        expect(newResult).toEqual([[1, 2], [2, 1]]);
    });
});
